/* eslint-disable @typescript-eslint/naming-convention */
export interface ISellerRegisterModel {

  fullAddress: string;
  nationalCode: string;
  identificationCode: string;
  birthDay: Date;
  token: string;
}

export class SellerRegisterModel implements ISellerRegisterModel {

  fullAddress: string;
  nationalCode: string;
  identificationCode: string;
  birthDay: Date;
  token: string;

  constructor(
    FullAddress: string,
    nationalCode: string,
    identificationCode: string,
    birthDay: Date,
    token: string
  ) {
    this.fullAddress = FullAddress;
    this.nationalCode = nationalCode;
    this.identificationCode = identificationCode;
    this.birthDay = birthDay;
    this.token = token;
  }
}
