import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { HttpClientModule, HTTP_INTERCEPTORS } from '@angular/common/http';
import { ReactiveFormsModule, FormsModule } from '@angular/forms';
import { AccountService } from '../../../data/service/auth/account.service';
import { AccountInterceptor } from '../../../core/utility/account.interceptor';
import { LoginComponent } from './account/login/login.component';
import { BuyerRegisterComponent } from './account/buyer-register/buyer-register.component';
import { SellerRegisterComponent } from './account/seller-register/seller-register.component';
import { AdminRegisterComponent } from './account/admin-register/admin-register.component';
import { TeacherRegisterComponent } from './account/teacher-register/teacher-register.component';
