/* eslint-disable @typescript-eslint/naming-convention */
export interface IAdminRegisterModel {

  phoneNumber: string;
  password: string;
  email: string;
  name: string;
  family: string;
  fullAddress: string;
  nationalCode: string;
  identificationCode: string;
  birthDay: Date;
}

export class AdminRegisterModel implements IAdminRegisterModel {

  phoneNumber: string;
  password: string;
  email: string;
  name: string;
  family: string;
  fullAddress: string;
  nationalCode: string;
  identificationCode: string;
  birthDay: Date;

  constructor(
    PhoneNumber: string,
    Password: string,
    Email: string,
    Name: string,
    Family: string,
    FullAddress: string,
    nationalCode: string,
    identificationCode: string,
    birthDay: Date
  ) {
    this.phoneNumber = PhoneNumber;
    this.password = Password;
    this.email = Email;
    this.name = Name;
    this.family = Family;
    this.fullAddress = FullAddress;
    this.nationalCode = nationalCode;
    this.identificationCode = identificationCode;
    this.birthDay = birthDay;
  }
}
