/* eslint-disable @typescript-eslint/naming-convention */
export interface IRegisterModel {

  phoneNumber: string;
  password: string;
  email: string;
  name: string;
  family: string;
  token: string;
  inviteId: number;
}

export class RegisterModel implements IRegisterModel {

  phoneNumber: string;
  password: string;
  email: string;
  name: string;
  family: string;
  token: string;
  inviteId: number;

  constructor(
    PhoneNumber: string,
    Password: string,
    Email: string,
    Name: string,
    Family: string,
    token: string,
    inviteId: number
    ) {
    this.phoneNumber = PhoneNumber;
    this.password = Password;
    this.email = Email;
    this.name = Name;
    this.family = Family;
    this.token = token;
    this.inviteId = inviteId;
  }
}
