/* eslint-disable @typescript-eslint/naming-convention */
import { Component, OnInit } from '@angular/core';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { AdminRegisterModel } from '../../../../../data/model/account/AdminRegisterModel';
import { AccountService } from '../../../../../data/service/auth/account.service';
import { IMembershipSubjectModel } from '../../../../../data/model/common/MembershipSubjectModel';
import { GAccount } from '../../../../../core/common/GAccount';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { ToastController, LoadingController } from '@ionic/angular';
import { GResponse } from '../../../../../core/common/GResponse';

@Component({
  selector: 'app-admin-register',
  templateUrl: './admin-register.component.html',
  styleUrls: ['./admin-register.component.scss']
})
export class AdminRegisterComponent implements OnInit {

  registerForm: FormGroup;

  constructor(
    private accountService: AccountService,
    public router: Router,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController) { }

  ngOnInit(): void {

    this.registerForm = this.fb.group({
      phoneNumber: ['', [Validators.required, Validators.minLength(10), Validators.maxLength(15)]],
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(100)]],
      name: ['', [Validators.required, Validators.maxLength(50)]],
      family: ['', [Validators.required, Validators.maxLength(100)]],
      address: ['', [Validators.required, Validators.maxLength(1000)]],
      nationalCode: ['', [Validators.required, Validators.maxLength(13)]],
      identificationCode: ['', [Validators.required, Validators.maxLength(13)]],
      birthDay: ['', [Validators.required]]
    });

    // this.accountService.membershipSubject.subscribe((data: IMembershipSubjectModel) => {

    //   switch (data.RequestType) {
    //     case GAccount.AdminRegisterType: {
    //       this.RegisterStatus(data.Code, data.Message);
    //       SharedIonic.dismissLoading(this.loadingController);
    //       break;
    //     }
    //   }
    // });
  }

  Register() {

    if (this.registerForm.valid) {

      SharedIonic.loading(this.loadingController);

      this.accountService.AdminRegister(
        new AdminRegisterModel(
          this.registerForm.value.phoneNumber,
          this.registerForm.value.password,
          this.registerForm.value.email,
          this.registerForm.value.name,
          this.registerForm.value.family,
          this.registerForm.value.address,
          this.registerForm.value.nationalCode,
          this.registerForm.value.identificationCode,
          this.registerForm.value.birthDay
        )
      ).subscribe(
        res => {
          AccountService.TokenRolesInit(res, this.registerForm.value.email);
          GResponse.MyCourseIds = [];
          GResponse.setCartCoursesCount(0);
          // GResponse.CartCoursesCount = 0;
          SharedIonic.dismissLoading(this.loadingController);
          this.RegisterStatus(200);
        },
        err => {
          this.RegisterStatus(AccountService.ErrorState);
          SharedIonic.dismissLoading(this.loadingController);
        }
      );
    }
  }

  RegisterStatus(code: number, responsMsg: string = '') {

    let msg = 'خطایی رخ داده';

    if (code === 200) {

      msg = 'عضویت با موفقیت انجام شد';
      SharedIonic.toast(this.toastController, msg);
      this.router.navigateByUrl('/');
      return;

    } else if (code === 423) {
      msg = 'با پشتیبانی تماس بگیرید';
    } else if (code === 404) {
      msg = 'انجام نشد';
    } else if (code === 400) {
      msg = 'ایمیل یا رمز عبور نامعتبر است';
    } else if (code === 406) {
      msg = 'ایمیل یا رمز عبور نامعتبر است';
    } else if (code === 0) {
      return;
    }

    SharedIonic.toast(this.toastController, msg);
  }
}
