/* eslint-disable @typescript-eslint/naming-convention */
import { Component, ElementRef, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { AccountService } from '../../../../../data/service/auth/account.service';
import { ILoginModel, LoginModel, TwoFactorChannel } from '../../../../../data/model/account/LoginModel';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { IMembershipSubjectModel } from '../../../../../data/model/common/MembershipSubjectModel';
import { GAccount } from '../../../../../core/common/GAccount';
import { GResponse } from '../../../../../core/common/GResponse';
import { OrderService } from '../../../../../data/service/order/order.service';
import { CourseService } from '../../../../../data/service/course/course.service';
import { G } from '../../../../../core/common/G';
// import { ReCaptchaV3Service } from 'ngx-captcha';
import { load } from 'recaptcha-v3';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.scss']
})
export class LoginComponent implements OnInit {

  loginForm: FormGroup;
  inputType = 'password';
  isShow = true;
  siteKey = '';
  twoFactor = false;
  chooseDelivery = false;
  sending = false;
  twoFactorChannel: TwoFactorChannel;
  deliveryDisabled = false;
  recoveryAvailable = false;
  deliveryNotice = '';

  constructor(
    private accountService: AccountService,
    public router: Router,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private courseService: CourseService,
    // private reCaptchaV3Service: ReCaptchaV3Service,
    private orderService: OrderService) { }


  ngOnInit(): void {

    this.siteKey = G.SiteKey;

    this.loginForm = this.fb.group({
      email: ['', [Validators.required, Validators.email]],
      password: ['', [Validators.required, Validators.minLength(3), Validators.maxLength(100)]],
      token2: ['']
    });
  }

  ionViewWillEnter() {

    this.twoFactor = false;
    this.chooseDelivery = false;
    this.twoFactorChannel = undefined;
    this.deliveryDisabled = false;
    this.recoveryAvailable = false;
    this.deliveryNotice = '';
  }

  togglePasswordText() {

    this.isShow = false;
    this.inputType = 'text';
  }

  toggleTextPassword() {

    this.isShow = true;
    this.inputType = 'password';
  }

  Login() {
    if (!this.loginForm.valid || this.sending) { return; }
    this.twoFactorChannel = undefined;
    this.loginForm.patchValue({ token2: '' });
    this.chooseDelivery = false;
    this.twoFactor = false;
    this.recoveryAvailable = false;
    this.deliveryNotice = '';
    this.submitLogin();
  }

  sendCode(channel: TwoFactorChannel) {
    if (this.sending) { return; }
    this.twoFactorChannel = channel;
    this.recoveryAvailable = false;
    this.deliveryNotice = '';
    this.loginForm.patchValue({ token2: '' });
    this.submitLogin();
  }

  Login2() {
    const code = String(this.loginForm.value.token2 || '').trim();
    if (!code) { return; }
    this.submitLogin(code);
  }

  private submitLogin(code?: string) {
    if (!this.loginForm.valid || this.sending) { return; }
    this.sending = true;
    SharedIonic.loading(this.loadingController);
    this.accountService.Login(new LoginModel(
      this.loginForm.value.email.trim(),
      this.loginForm.value.password,
      'failed', code, this.twoFactorChannel
    )).subscribe(
      res => {
        this.sending = false;
        AccountService.TokenRolesInit(res, this.loginForm.value.email.trim());
        this.afterLogin();
        SharedIonic.dismissLoading(this.loadingController);
        this.LoginStatus(200);
      },
      () => {
        this.sending = false;
        SharedIonic.dismissLoading(this.loadingController);
        this.LoginStatus(AccountService.ErrorState, AccountService.ErrorMessage);
      }
    );
  }

  async afterLogin() {

    this.orderService.GetUserCart().subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {
          if (res.data.courses == null) {
            GResponse.setCartCoursesCount(0);
            // GResponse.CartCoursesCount = 0;
          } else {
            GResponse.setCartCoursesCount(res.data.courses.length);
            // GResponse.CartCoursesCount = res.data.courses.length;
          }
        } else {
          GResponse.setCartCoursesCount(0);
          // GResponse.CartCoursesCount = 0;
        }
      }
    );

    this.courseService.GetUserCoursesId().subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {
          GResponse.MyCourseIds = res.data;
        } else {
          GResponse.MyCourseIds = [];
        }
      }
    );
  }

  async LoginStatus(code: number, responsMsg: any = '') {

    let msg = 'خطایی رخ داده';

    if (code === 200) {

      let returnUrl = '/';

      for (let i = 0; i < localStorage.length; i++) {
        if (localStorage.key(i) === 'returnUrl') {
          returnUrl = localStorage.getItem('returnUrl');
          localStorage.removeItem('returnUrl');
        }
      }

      msg = 'ورود با موفقیت انجام شد';
      SharedIonic.toast(this.toastController, msg);
      this.router.navigateByUrl(returnUrl);
      return;

    } else if (code === 423) {
      msg = 'اکانت شما غیر فعال شده است';
    } else if (code === 665) {
      this.chooseDelivery = true;
      this.twoFactor = false;
      this.twoFactorChannel = undefined;
      return;
    } else if (code === 666) {
      this.chooseDelivery = false;
      this.twoFactor = true;
      this.recoveryAvailable = responsMsg?.deliveryStatus === 'disabled';
      this.deliveryDisabled = responsMsg?.deliveryStatus === 'disabled';
      msg = responsMsg?.deliveryStatus === 'device' ? 'در پنل یکی از دو ادمین واردشده، ایمیل این حساب را به‌عنوان مقصد انتخاب کنید و کد آن را وارد کنید.' : this.deliveryDisabled
        ? 'کد ساخته شد، اما ارسال ایمیل فعلاً غیرفعال است.'
        : this.twoFactorChannel === 'sms'
          ? 'درخواست پیامک در سرویس ثبت شد؛ تحویل به گوشی هنوز تأیید نشده است.'
          : 'کد ورود ارسال شد؛ لطفاً آن را وارد کنید.';
      const destination = typeof responsMsg?.destination === 'string' && /^09\*{7}[0-9]{2}$/.test(responsMsg.destination)
        ? ` مقصد ثبت‌شدهٔ حساب: ${responsMsg.destination}.` : '';
      this.deliveryNotice = msg + destination;
    } else if (code === 502 || code === 503) {
      this.recoveryAvailable = responsMsg?.recoveryAvailable === true;
      this.deliveryNotice = '';
      if (this.recoveryAvailable) {
        this.chooseDelivery = false;
        this.twoFactor = true;
        this.deliveryDisabled = false;
      }
      if (responsMsg?.code === 'two_factor_sms_not_configured') {
        msg = 'سرویس پیامک روی سرور تنظیم نشده است؛ روش ایمیل را انتخاب کنید.';
      } else if (responsMsg?.code === 'two_factor_phone_missing') {
        msg = 'شماره موبایل حساب ثبت نشده است؛ ایمیل یا دستگاه واردشده را انتخاب کنید.';
      } else if (responsMsg?.code === 'two_factor_phone_invalid') {
        msg = 'شماره موبایل ثبت‌شدهٔ حساب معتبر نیست؛ آن را در پروفایل اصلاح کنید یا روش دیگر را انتخاب کنید.';
      } else if (responsMsg?.code === 'two_factor_delivery_failed') {
        msg = 'ارسال کد انجام نشد؛ دوباره تلاش کنید یا روش دیگر را انتخاب کنید.';
      } else {
        msg = 'سرویس ورود موقتاً در دسترس نیست؛ کمی بعد دوباره تلاش کنید.';
      }
    } else if (code === 777) {
      msg = 'کد ورود نامعتبر یا منقضی شده است؛ آخرین کد را وارد کنید یا کد جدید بگیرید.';
    } else if (code === 404) {
      msg = 'ایمیل یا رمز عبور نامعتبر است';
    } else if (code === 400) {
      if (responsMsg === 'User LockedOut') {
        msg = 'اکانت شما به مدت 1 ساعت مسدود شده است';
      } else if (responsMsg === 'User Dose not Exist') {
        msg = 'ایمیل یا رمز عبور نامعتبر است';
      } else if (responsMsg === 'Bot Detected!') {
        msg = 'شما ربات شناخته شدید';
      } else {
        msg = 'ایمیل یا رمز عبور نامعتبر است';
      }
    } else if (code === 406) {
      msg = 'ایمیل یا رمز عبور نامعتبر است';
    } else if (code === 0) {
      return;
    }

    SharedIonic.toast(this.toastController, msg);
  }
}
