/* eslint-disable @typescript-eslint/naming-convention */
export type TwoFactorChannel = 'email' | 'sms' | 'device';

export interface ILoginModel {

  email: string;
  password: string;
  token: string;
  token2: string;
  twoFactorChannel?: TwoFactorChannel;
}

export class LoginModel implements ILoginModel {

  email: string;
  password: string;
  token: string;
  token2: string;
  twoFactorChannel?: TwoFactorChannel;

  constructor(
    Email: string,
    Password: string,
    token: string,
    token2?: string,
    twoFactorChannel?: TwoFactorChannel
  ) {
    this.email = Email;
    this.password = Password;
    this.token = token;
    this.token2 = token2;
    this.twoFactorChannel = twoFactorChannel;
  }
}
